"""Grounded Russian narrative assembled solely from deterministic tool results."""
def span(item,digits=2):
    if item is None:return 'не установлен'
    return f"{item['low']:.{digits}f}" if abs(item['high']-item['low'])<1e-9 else f"{item['low']:.{digits}f}–{item['high']:.{digits}f}"
def render(state,data,r):
    p=[];level=r.get('result_level')
    labels={'MEASURED':'Расчёт по измеренным характеристикам партии','LITERATURE_ESTIMATE':'Литературная оценка для сопоставимой навозной жижи','HYPOTHETICAL_SCENARIO':'Условный сценарий: если ваш навоз сопоставим с исследованной навозной жижей'}
    if r.get('methane_potential_m3'):
        p.append(labels.get(level,'Оценка')+'. Это потенциал CH₄, а не подтверждённый выход вашей установки.')
        p.append(f"Оценочная влажная масса: {span(r.get('wet_mass_kg'))} кг; масса VS: {span(r.get('vs_mass_kg'))} кг. Потенциальный метан: {span(r['methane_potential_m3'])} м³ CH₄ ({span(r['methane_potential_l'],0)} л), при {r.get('gas_reference')}. Влажностный базис газа требует проверки.")
        if r.get('profile_id'):p.append('Источник: Oliveira и соавт., DOI 10.1007/s43153-025-00592-x. Плотность 1,013 кг/л; VS 10,8 ± 0,64% влажной массы (таблица 1). Для необработанного RM1 использован грубый графический диапазон BMP 200–250 мл CH₄/г VS между основными делениями рисунка 1a. Это не точное среднее и не доверительный интервал. Опыт: 37 °C, 27 суток; эти условия не назначены вашей установке.')
        if r.get('fuel_energy_kwh'):p.append(f"Ориентировочная энергия топлива: {span(r['fuel_energy_kwh'])} кВт·ч по справочнику FNR, 9,97 кВт·ч/м³ чистого метана, при допущении сопоставимых опорных условий. Это не электрическая энергия и не выручка; реальный выход и КПД неизвестны.")
        if not r.get('raw_biogas_m3'):p.append('Общий объём биогаза не рассчитан: доля метана неизвестна. Метан и сырой биогаз имеют разные состав и цену.')
    else:p.append('Для указанного вида и состояния сырья пока нет полного проверенного сопоставимого набора характеристик и BMP. Числа из другого вида навоза или компоста не переношу. '+r.get('message',''))
    offers=r.get('market',{}).get('offers',[])
    if offers:
        offer=offers[0];age=r['market'].get('cache_age_hours',0)
        p.append(f"Рыночный ориентир, Караганда: каталог StroiTaxi показывает приблизительно {offer['value']:.0f} ₸/т. Дата публикации неизвестна; получено {offer['received_at']}; возраст сохранённой записи {age:.1f} ч. Актуальность цены не подтверждена. "+(f"Для оценочной массы это около {span(r.get('catalog_reference_value_kzt'))} ₸ по цене предложения. " if r.get('catalog_reference_value_kzt') else '')+'Это предложение продавца: покупатель для вашей партии, влажность, доставка и минимальный объём не подтверждены; доход от продажи не установлен.')
    else:p.append('Сопоставимого предложения с подтверждёнными единицами и регионом сейчас нет в доступном кеше/источниках. Статус поиска: '+r.get('market',{}).get('status','error')+'. Цены не подставлены.')
    p.append('Чистую прибыль продажи и переработки пока нельзя ранжировать: нет подтверждённого покупателя навоза/сырого биогаза, условий допустимости продажи газа, реального извлечения, энергозатрат, подготовки, хранения, перевозки и обращения с дигестатом. Тариф природного газа не принят за цену сырого биогаза. Газ на продажу и тот же газ на энергию не суммируются.')
    economic=r.get('user_economic_scenario',{})
    if economic.get('status')=='ok':
        rows=economic['endpoints']
        p.append(f"Отдельно рассчитан условный сценарий по введённым вами ценам: результат переработки {min(x['processing_net_profit'] for x in rows):.2f}–{max(x['processing_net_profit'] for x in rows):.2f} {rows[0]['currency']}; выручка продажи сырья {rows[0]['sale_revenue']:.2f}–{rows[-1]['sale_revenue']:.2f} {rows[0]['currency']}. Использован прежний calculate_profitability; хранение, транспорт и дигестат должны входить в введённые эксплуатационные затраты. Реальная сделка и все затраты не проверены, поэтому окончательной рекомендации нет.")
    if state.value('reactor_total_volume_l'):p.append(f"В памяти сохранён полный объём реактора {state.value('reactor_total_volume_l'):g} л. Рабочий объём, место для инокулюма и газовое пространство ещё не установлены.")
    if not data['region_confirmed']:p.append('Караганда использована как регион по умолчанию панели; ваш регион ещё не подтверждён.')
    p.append('Диапазон показывает чувствительность к литературным параметрам; его покрытие не проверено. Hafner BMP для этого материала не вызывался. Литературные свойства не записаны как измерения вашей партии.')
    return p
